def update_comment(code, comment):
    url = f"{SUPABASE_URL}/rest/v1/majors?code=eq.{code}"
    data = json.dumps({'xuefeng_comment': comment}).encode('utf-8')
    req = urllib.request.Request(url, data=data, method='PATCH')
    req.add_header('apikey', SUPABASE_KEY)
    req.add_header('Authorization', f'Bearer {SUPABASE_KEY}')
    req.add_header('Content-Type', 'application/json')
    req.add_header('Prefer', 'return=minimal')
    
    try:
        with urllib.request.urlopen(req, context=ctx) as response:
            return True, response.status
    except urllib.error.HTTPError as e:
        return False, e.code

def main():
    print("=" * 70)
    print("🚀 开始更新雪峰点评...")
    print("=" * 70)
    
    success = 0
    fail = 0
    skipped = 0
    
    for code, comment in expanded_comments.items():
        print(f"\n正在更新: {code}")
        ok, status = update_comment(code, comment)
        if ok or status in [200, 204]:
            success += 1
            print(f"✅ 成功，长度: {len(comment)}字符")
        elif status == 409:
            skipped += 1
            print(f"⏭️ 已存在")
        else:
            fail += 1
            print(f"❌ 失败: {status}")
        time.sleep(0.1)
    
    print(f"\n更新完成! 成功: {success}, 失败: {fail}, 跳过: {skipped}")

if __name__ == "__main__":
    main()
